class TTLCache:
    def __init__(self, maxsize=128, ttl=600, timer=time.monotonic, typed=False):
        # Initialize cache with maximum size and duration
        self.maxsize = maxsize
        self.ttl = ttl
        self.timer = timer
        self.ttl_dict = {}
        self.item_dict = {}

    def _update_ttl(self, key):
        # Update the TTL for a specific key
        current_time = self.timer()
        if key in self.ttl_dict:
            self.ttl_dict[key] = current_time + self.ttl

    def _remove_expired_items(self):
        # Remove expired items if TTL exceeds
        for key, expire_time in list(self.ttl_dict.items()):
            current_time = self.timer()
            if expiration_time < current_time:
                del self.ttl_dict[key]
                del self.item_dict[key]

    def __getitem__(self, key):
        self._remove_expired_items()
        if key in self.item_dict:
            # Retrieve the item with updated TTL
            result = self.item_dict[key]
            current_time = self.timer()
            self.ttl_dict[key] = current_time + self.ttl
            return result
        raise KeyError(key)

    def __setitem__(self, key, value):
        self._update_ttl(key)
        self.item_dict[key] = value

    def __delitem__(self, key):
        # Remove an item and its associated TTL
        if key in self.item_dict:
            del self.item_dict[key]
            del self.ttl_dict[key]
        raise KeyError(key)

    def __contains__(self, key):
        # Check if the key exists in the cache
        self._remove_expired_items()
        return key in self.item_dict

