    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    :param cache: Cache dictionary to store results.
    :param key: Key for looking up the result in the cache.
    :param lock: Optional mutex to ensure thread safety.
    :return: Decorated method.
    """
    def wrapper(func):
