def extostr(e, max_level=30, max_path_level=5):
    if not isinstance(e, Exception):
        raise ValueError("Input must be an instance of Exception.")
    tracebacks = traceback.extract_stack()[-max_level:]
    error_level = len(tracebacks) - 1
    if error_level < max_path_level:
        error_level = max_path_level - 1
    short_description = f"Error {error_level + 1}: {e}"
    traceback_str = "\n".join(tracebacks[-error_level:])
    return short_description + "\n" + traceback_str

def extostr(self, e, max_level=30, max_path_level=5):
        if not isinstance(e, Exception):
            raise TypeError("Input must be an instance of Exception")
        if max_level < 1:
            raise ValueError("max_level must be a positive integer")
        if max_path_level < 1:
            raise ValueError("max_path_level must be a positive integer")

        stack = []
        current_level = 1
        visited = set()

        # Create a stack with the exception itself as the first element
        stack.append((e, 0))

        while stack:
            if current_level > max_level:
                break
            cur_exception, cur_depth = stack.pop(0)
            if cur_depth in visited:
                continue
            visited.add(cur_depth)

            if cur_depth > 0:
                stack.append((self.extract ExceptionMethods(cur_exception), cur_depth + 1))

            if cur_depth > max_path_level:
                continue

            # Format the exception message and return
            formatted_message = f"{cur_exception.__class__.__name__}: {str(cur_exception)}. "
            formatted_message += self.generate_traceback(cur_exception, cur_depth)
            return formatted_message

        return "No exception details found"

