def integral(bins, edges):
    if len(bins) != len(edges) - 1:
        raise ValueError("bins and edges must have the same length")

    area = 0
    for i in range(len(bins) - 1):
        area += (edges[i + 1] - edges[i]) * (bins[i + 1] - bins[i])

    return area

def integral(bins, edges):
    if not hasattr(edges, '__len__'):
        raise ValueError("edges must be a list-like object")

    if len(edges) < 2:
        raise ValueError(" edges must contain at least two elements")

    if not hasattr(bins, '__len__'):
        raise ValueError("bins must be a list-like object")

    if len(bins) != len(edges) - 1:
        raise ValueError("bins and edges must have the same length")

    practical_bins = [edges[0]] + bins + [edges[-1]]

    # Compute bin widths
    bin_widths = [practical_bins[i + 1] - practical_bins[i] for i in range(len(practical_bins) - 1)]

    # Compute integral
    integral = [bin_widths[i] * bins[i] for i in range(len(bins))]

    return integral

