def formatmany(
    self,
    sql: typing.Union[str, bytes],
    many_params: typing.Union[typing.Iterable[Dict[typing.Union[str, int], typing.Any]],
                           typing.Iterable[typing.Sequence[typing.Any]]],
) -> typing.Tuple[typing.Union[str, bytes], typing.Union[
    typing.List[typing.Dict[typing.Union[str, int], typing.Any]],
    typing.List[typing.Sequence[typing.Any]]
]]:
    # Check if SQL is in bytes
    if isinstance(sql, bytes):
        sql = sql.decode('utf-8')

    # Initialize output
    formatted_sql = sql
    converted_params = []

    # Iterate over each set of parameters
    for params in many_params:
        if isinstance(params, dict):
            # Convert dictionary to out-style query
            converted_param_str = ''
            for key, value in params.items():
                converted_param_str += f'${key}={escape_value(value)} '
            converted_params.append(converted_param_str.strip())
        else:
            # Convert tuple to out-style query
            converted_params.append(',')
            for value in params:
                converted_params.append(escape_value(value))

    # Join converted parameters with SQL query
    formatted_sql = formatted_sql.replace('?', converted_params)

    return formatted_sql, converted_params

