import zipfile

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    if not zipfile.is_zipfile(zip_path):
        raise ValueError("The provided path does not point to a valid zip file.")

    data_dict = {}

    try:
        with zipfile.ZipFile(zip_path, 'r') as zfile:
            for item in zfile.namelist():
                basename = item.split('/')[-1].rsplit('/', 1)[0] if '/' in item else None
                if basename:
                    if basename in data_dict:
                        data_dict[basename].append(item)
                    else:
                        data_dict[basename] = [item]
    except Exception as e:
        raise Exception(f"An error occurred while processing the zipfile: {str(e)}")

    return data_dict

