    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    data_dict = {}  # Dictionary to store file data by their XML basename

    try:
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            for xml_file in zip_ref.namelist():
                file_data = zip_ref.read(xml_file)
                basename = xml_file.split('/')[-1]
                if basename in data_dict:
                    data_dict[basename].append(file_data)
                else:
                    data_dict[basename] = [file_data]

    except FileNotFoundError:
        print(f"Error: Zip file not found at {zip_path}")
        return {}

    except Exception as e:
        print(f"An error occurred: {e}")
        return {}

    return data_dict

import zipfile

def _explore_zipfile(zip_path):
    try:
        with zipfile.ZipFile(zip_path) as zip_ref:
            files = zip_ref.namelist()
            data_by_base = {}
            for file in files:
                if file.endswith('.xml'):  # Assuming XML files contain the data
                    base_name = file.rsplit('/', 1)[-1].rstrip('.xml')
                    data_by_base[base_name] = zip_ref.read(file).decode('utf-8')
            return data_by_base
    except Exception as e:
        print(f"An error occurred: {e}")
        return None

