def pretty(self, indent=0, debug=False):
    if not isinstance(indent, int):
        raise ValueError("Indent must be an integer")

    if debug:
        import inspect
        print(f"Debug print from pretty: Indent = {indent}")

    class Node:
        def __init__(self, value, indent):
            self.value = value
            self.indent = indent

        def __str__(self):
            leading_spaces = ' ' * self.indent
            return f"{leading_spaces}{self.value}\n"

    def visit(node):
        if isinstance(node, str):
            return Node(node, indent)
        elif isinstance(node, list):
            return [visit(child) for child in node]
        elif isinstance(node, dict):
            return {key: visit(value) for key, value in node.items()}
        else:
            return None

    root = visit(self)
    return ''.join(str(node) for node in root)

def pretty(self, indent=0, debug=False):
    if not hasattr(self, '__str__'):
        raise TypeError("Object does not have a str representation.")
    string = self.__str__()
    if indent > 0:
        a = (indent - 1) * " " + "|  "
        rep = f'{"-" * indent}{string}\n'
        for s in string.splitlines():
            rep += f'{a}{s}\n'
        return rep
    else:
        if debug:
            return 'Debug Mode: ' + string
        return string

