def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for expr in args:
        if isinstance(expr, tuple) and expr[0] == "&":
            if expr[1] == "A" or expr[1] == "A|" or expr[1] == "A&" or expr[1] == "A|":
                result.append(expr[1])
            elif expr[1] == "B" or expr[1] == "B|":
                result.append(expr[1])
            else:
                result.append(expr[1])
        elif isinstance(expr, tuple) and expr[0] == "|":
            if expr[1] == "A" or expr[1] == "A&" or expr[1] == "A|" or expr[1] == "A^":
                result.append(expr[1])
            elif expr[1] == "B" or expr[1] == "B|":
                result.append(expr[1])
            else:
                result.append(expr[1])
        else:
            result.append(expr)
    return result

def absorb(self, args):
    if not args or len(args) < 1:
        raise ValueError("Args sequence must not be empty")

    result = []
    for expr in args:
        if expr is None or expr == '':
            raise ValueError("Invalid expression found in args sequence")

        if '|' in expr:
            # Perform absorption: A & (A | B) = A, A | (A & B) = A
            left, right = expr.split('|')
            if left and right and (left == left.strip or right == right.strip):
                result.append(left.strip())
                continue

        elif '&' in expr:
            # Perform negative absorption: A & (~A | B) = A & B, A | (~A & B) = A | B
            left, right = expr.split('&')
            if left and right and (left == left.strip or right == right.strip):
                result.append(right.strip())
                continue

        result.append(expr)

    return result

def absorb(self, args):
    if not args:
        return []

    result = []
    for i, arg_i in enumerate(args):

        if isinstance(arg_i, tuple) and len(arg_i) == 3:
            op, arg_j, arg_k = arg_i
            if op == 'and':
                if arg_j == arg_i:
                    result.append(arg_i)
                elif arg_k == arg_i:
                    result.append(arg_i)
            elif op == 'or':
                if arg_j == arg_i:
                    result.append(arg_i)
                elif arg_k == arg_i:
                    result.append(arg_i)
        else:
            result.append(arg_i)

    return result

