def _fromutc(self, dt):
    # Calculate the offset in seconds of the 'self.tz' timezone from_utc
    switchtz_offset_sec = self.tz.utcoffset(dt, isdst=False)

    # Calculate the offset in seconds of the 'new_tz' timezone from_utc
    newtz_offset_sec = new_tz.utcoffset(dt, isdst=False)

    # If the dt is ambiguous or in a 'fold' state, adjust the new_tz.datetime
    if dt.tzinfo.utcoffset(None)+switchtz_offset_sec != new_tz_offset_sec:
        new_tz_offset = newtz_offset_sec - switchtz_offset_sec
    else:
        new_tz_offset = 0

    return new_tz.localize(dt, is_dst=False, tzinfo_offset=new_tz_offset)

