            output, error = process.communicate()
            if process.returncode != 0:
                if error:
                    if verbose:
                        print(f"Command failed with error: {error.decode('utf-8')}")
                else:
                    if verbose:
                        print(f"Command failed with return code {process.returncode}")
                return None
            return output.decode('utf-8')
        except Exception as e:
            if verbose:
                print(f"An error occurred while running command {command}: {e}")
            return None

import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    try:
        if not commands:
            print("No commands provided.")
            return

        if not args:
            print("No arguments provided for the commands.")
            return

        process = subprocess.Popen(commands, args=args, cwd=cwd, shell=False, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)

        if verbose:
            print(f Running command: {" ".join(commands + args)} with cwd={cwd} and env={env}")

        stdout, stderr = process.communicate()

        status = process.returncode

        if status == 0:
            print(stdout.strip())
            if not hide_stderr:
                print(stderr.strip())
        else:
            print(f"Command failed with status {status}:")
            print(stdout.strip())
            if not hide_stderr:
                print(stderr.strip())

    except Exception as e:
        print(f"An error occurred: {e}")

