def next_version(version):
    if not isinstance(version, (str, int)):
        raise ValueError('Version must be a string or an integer')
    if not version:
        raise ValueError('Version cannot be empty')

    def is_zero_prefixed(v):
        return isinstance(v, int) and v == 0

    def get_zero_padding_len(version):
        if is_zero_prefixed(version):
            return 0
        return max(1, int(log10(abs(version)) + 1))

    version_len = len(str(version))
    version_base = int(version[:version_len - get_zero_padding_len(version)])

    next_version_base = version_base + 1
    next_version_str = str(next_version_base) + (version[version_len - get_zero_padding_len(version):] if not is_zero_prefixed(version) else '')

    return next_version_str

def next_version(version):
    try:
        if version[0].isdigit():
            # Extract the numeric part and increment it
            numeric_part = int(version[1:])
            numeric_part += 1
            return '.'.join((version[:1], numeric_part))
        else:
            # Leading character is non-numeric, add a zero prefix to the result
            return '0.' + version
    except (IndexError, ValueError) as e:
        raise ValueError(f"Invalid version format: {version}. Please use a version number with at least one non-zero digit as the prefix.")

def next_version(version):
    if version == "":
        raise ValueError("Identifier must not be empty")

    def prepend_zero_if_needed(number):
        return f"0{number}" if number == 0 else str(number)

    digits = ''.join(filter(lambda c: c.isdigit(), version))
    try:
        current_version_int = int(digits)
    except ValueError:
        raise ValueError("Invalid version number format")

    current_version_int += 1
    return prepend_zero_if_needed(current_version_int)

