    """
    error_messages = []
    for version in version_dirs:
        inventory_path = os.path.join(version, 'inventory.txt')
        if not os.path.exists(inventory_path):
            error_messages.append((version, f"Inventory file not found in {version}"))
            continue

        with open(inventory_path, 'r') as inv_file:
            current_inventory = {int(line.strip()): set() for line in inv_file}

        root_inventory_path = os.path.join(version, 'root_inventory.txt')
        if not os.path.exists(root_inventory_path):
            error_messages.append((version, f"Root inventory file not found in {version}"))
            continue

        with open(root_inventory_path, 'r') as root_inv_file:
            root_inventory = {int(line.strip()): set() for line in root_inv_file}

        for line in inv_file:
            line_number, file_name = line.strip().split(':')
            file_name = file_name.split('/')[-1]
            file_digest = file_name.split('.')[1]
            if file_name in current_inventory:
                if file_digest not in current_inventory[file_name]:
                    error_messages.append((version, f"Digest mismatch for {file_name}: expected {file_digest} but got {current_inventory[file_name].pop()}"))
                    break

        #keeping a record of any content digests different from those in the root inventory
        for line in inv_file:
            line_number, file_name = line.strip().split(':')
            file_name = file_name.split('/')[-1]
            file_digest = file_name.split('.')[1]
            if file_name not in root_inventory:
                error_messages.append((version, f"Unknown file {file_name} in this inventory"))

    return all(not msg for version, msg in error_messages)

