    return round(size_value)

def size_to_bytes(size: str) -> int:
    size_chunks = size.split()
    if len(size_chunks) < 2:
        raise ValueError("Invalid input: expected size with a unit (e.g., '500K')")

    number = float(size_chunks[0])
    unit = size_chunks[1]

    if unit.lower() == "b":
        return int(number)
    elif unit.lower() == "k":
        return int(number * 1024)
    elif unit.lower() == "m":
        return int(number * 1024 * 1024)
    elif unit.lower() == "g":
        return int(number * 1024 * 1024 * 1024)
    else:
        raise ValueError("Unsupported unit: {unit}. Expected 'B', 'K', 'M', or 'G'")

import re

def size_to_bytes(size: str) -> int:
    if not size:
        raise ValueError("Size cannot be empty.")

    pattern = re.compile(r'(\d+)([A-Z][a-z]+)')
    match = pattern.match(size)

    if match:
        parts = match.groups()
        number = int(parts[0])
        units = parts[1]

        mapping = {'K': 1024, 'M': 1024**2, 'G': 1024**3, 'T': 1024**4}
        return round(number * mapping[units])
    else:
        raise ValueError("Invalid size format.")

