def string_to_int(string: str, alphabet: List[str]) -> int:
    if not string or not alphabet:
        raise ValueError("Input string or alphabet cannot be empty.")

    # Check if the alphabet includes all characters in the string
    used_chars = set()
    for char in string:
        if char not in alphabet:
            raise ValueError(f"String '{string}' contains characters not in the alphabet '{alphabet}'.")
        used_chars.add(char)
    if len(used_chars) < len(alphabet):
        raise ValueError("String must contain all characters from the alphabet.")

    # Calculate the numeric value of the string
    value = 0
    exponent = len(string) - 1
    for char in string:
        value += alphabet.index(char) * (10 ** exponent)
        exponent -= 1

    return int(value)

def string_to_int(string: str, alphabet: List[str]) -> int:
    if string is None or alphabet is None:
        raise ValueError("Input strings cannot be None")
    base = len(alphabet)
    if base <= 1:
        raise ValueError("Alphabet cannot have <= 1 character")

    result = 0
    index = 0
    for char in reversed(string):
        if char not in alphabet:
            raise ValueError(f"Invalid character '{char}' in string")
        index = alphabet.index(char)
        result = result * base + index

    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    if string is None or string == "":
        raise ValueError("String cannot be None or empty")

    if any(char not in alphabet for char in string):
        raise ValueError("All characters in the string must be in the alphanumeric character set")

    def char_to_int(char):
        return alphabet.index(char)

    result = 0
    for i, char in enumerate(reversed(string)):
        result += char_to_int(char) * (len(alphabet) ** i)

    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    alphabet_index = {char: index for index, char in enumerate(alphabet)}
    result = 0
    for i, char in enumerate(reversed(string)):
        if char not in alphabet_index:
            raise ValueError(f"Invalid character '{char}' in input string.")
        result += alphabet_index[char] * (len(alphabet) ** i)
    return result

