import requests

def get_repo_archive(url: str, destination_path: Path) -> Path:
    if not url.endswith('.tar.gz'):
        raise ValueError("URL must end with .tar.gz")

    archive_name = url.split('/')[-1].split('.')[0]
    destination_dir = destination_path / archive_name

    try:
        response = requests.get(url, stream=True)
        response.raise_for_status()

        with open(destination_dir / archive_name, 'wb') as file:
            for chunk in response.iter_content(chunk_size=1024):
                file.write(chunk)

        shutil.unpack_archive(destination_dir / archive_name, destination_dir)
        return destination_dir
    except requests.RequestException as e:
        raise Exception(f"Failed to retrieve archive: {e}")
    except FileNotFoundError as e:
        raise Exception(f"Archive not found: {e}")
    except shutil.Error as e:
        raise Exception(f"Failed to unpack archive: {e}")
    except Exception as e:
        raise Exception(f"An error occurred: {e}")

