def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    # Check if ignored is a list
    if not isinstance(ignored, list):
        raise ValueError('The argument must be a list')

    # Obtain the list of ignored file names using the git command
    command = ['git', 'ls-files', '--ignored']
    try:
        result = subprocess.run(command, capture_output=True, text=True, check=True)
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f'Failed to retrieve ignored file names: {e.output}')

    # Sort the list of ignored file names
    ignored_files = sorted(result.stdout.strip.split('\n'))

