    for time_format in ALLOWED_TIME_FORMATS:
        match = re.search(time_format, dt_str)
        if match:
            datetime_obj = datetime(int(match.groups()[0]), int(match.groups()[1]) if len(match.groups()) >= 2 else 1, tzinfo=timezone.utc)
            return datetime_obj

    for time_zone_offset, offset in ALLOWED_TIME_ZONE_OFFSETS.items():
        if dt_str.endswith(time_zone_offset):
            return datetime.utcnow() + offset

    raise ValueError("Failed to parse the ISO-8601 datetime string")

