from typing import Tuple, Set, Callable

def find_tags(text: str, replacer: Callable = None) -> Tuple[Set, str]:
    tags = set()
    i = 0
    while i < len(text):
        if text[i] == '<':
            stack = []
            while i < len(text) and not stack:
                if text[i] == '<' and text[i + 1] == '/':
                    i += 2
                elif text[i] == '<':
                    stack.append(i)
                    i += 1
                else:
                    i += 1
            if not stack:
                if i > 0:
                    tags.add(text[:i].strip())
                    if replacer:
                        text = text[:i].replace(text[i:i + 2], replacer(text[i:i + 2]))
                else:
                    tags.update(replacer(text[i:]) if replacer else text[i:]) if i < len(text) else set()
            elif replacer:
                text = text[:stack[-1]].replace(text[stack[-1] + 2:i], replacer(text[stack[-1] + 2:i]))
        else:
            if text[i - 1] == '<':
                tags.add(text[i:].strip())
            i += 1
    return tags, text

def find_tags(text: str, replacer: callable = None) -> Tuple[set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    found = False
    original_text = text

    for i in range(len(text)):
        if text[i] == '[' and i < len(text) - 1:
            if text[i+1] != '[':
                start_tag = i
                found = True
            else:
                # Ignore triple brackets in code blocks
                while text[i+1] == '[' and i + 1 < len(text) - 1:
                    i += 1
    if found:
        start_tag += 1
        tag_word = text[start_tag:i]
        tags.add(tag_word)
        if replacer:
            original_text = original_text[:start_tag] + replacer(tag_word) + original_text[i+1:]
        return tags, original_text
    else:
        return tags, original_text

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    import re

    def clean_tag(tag):
        if replacer:
            tagged_text = f"{tag!r}"
            return replacer(tagged_text)
        else:
            return tag

    tags = set(re.findall(r'\[[^\]]*\]', text))
    cleaned_tags = [clean_tag(tag) for tag in tags]

    # Clean up missing closing tags
    stack = []
    result = ''
    for i in range(len(text)):
        if text[i] == '[':
            stack.append(i)
        elif text[i] == ']':
            if not stack:
                raise ValueError("Unmatched closing tag")
            start = stack.pop()
            result += text[start:i]
            if i < len(text) - 1:
                result += ' '
    if stack:
        raise ValueError("Unmatched opening tag")

    return set(cleaned_tags), result.strip()

