import xml.etree.ElementTree as ET

def verify_relayable_signature(public_key, doc, signature):
    try:
        # Parse the XML document
        root = ET.fromstring(doc)

        # Extract the signature element
        signature_element = root.find('.//ds:Signature', namespaces={'ds': 'http://www.w3.org/2000/09/xmldsig#'})

        if signature_element is None:
            return False  # Signature element not found

        # Verify the signature using public key
        signature_verified = signature_element.check_signature(public_key)

        return signature_verified
    except ET.ParseError:
        return False  # Error parsing the XML document
    except Exception as e:
        return False  # Other exception occurred during verification

